'use strict';
const assert=require('assert'),fs=require('fs'),os=require('os'),path=require('path');
const schema=require('./estado-v2'),{novo,migrar,validar,avancar,regenerar}=schema,{acoes,executar,ciclo}=require('./motor-v2'),{gravar,carregar,anexar,anexarCiclo}=require('./persistencia-v2'),{perceber}=require('./percepcao-v2'),{executarCiclos}=require('./ilha');
let total=0;function t(nome,fn){return Promise.resolve().then(fn).then(()=>{total++;console.log('OK '+nome)})}
(async()=>{
await t('contrato V5 e fonte única do ciclo',()=>{const e=novo();validar(e);assert.equal(e.versao,schema.VERSAO);assert(Number.isInteger(e.mundo.tempo.ciclo));assert(!('ciclos'in e.mundo.tempo));assert(!('ultimoCiclo'in e))});
await t('estado incompleto falha claramente',()=>assert.throws(()=>validar({versao:schema.VERSAO}),/Estado V2 inválido/));
await t('migração V2, V3 e V4 preserva recursos, necessidades, memória e auditoria',()=>{for(const versao of [2,3,4]){const e=novo();e.versao=versao;e.mundo.tempo.ciclos=e.mundo.tempo.ciclo;e.ultimoCiclo=1;e.seres.icaro.inventario.agua=3;e.memorias=[{texto:'memória anterior'}];e.historico={eventos:[{ciclo:4}],decisoes:[{ciclo:4}]};const m=migrar(e);assert.equal(m.versao,schema.VERSAO);assert.equal(m.seres.icaro.inventario.agua,3);assert.equal(m.memorias[0].texto,'memória anterior');assert.equal(m.historico.eventos.length,1);assert(!('ciclos'in m.mundo.tempo))}});
await t('migração ambígua é recusada sem descarte',()=>assert.throws(()=>migrar({versao:2,mundo:{ecossistema:{}},seres:{}}),/Migração V2 cancelada/));
await t('persistência conserva o estado lógico',()=>{const d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-v3-')),f=path.join(d,'estado.json'),e=novo();e.memorias.push({texto:'auditável'});gravar(f,e);assert.deepStrictEqual(carregar(f),e);fs.rmSync(d,{recursive:true,force:true})});
await t('ação permitida aplica consequência calculada do estoque',()=>{const e=novo(),s=e.seres.icaro;s.local='rio';const antes=e.mundo.ecossistema.agua.nascente,r=executar(e,s,'coletar_agua');assert(r.quantidade>0);assert(e.mundo.ecossistema.agua.nascente<antes);assert(s.inventario.agua>8)});
await t('ação inválida não muda o estado',()=>{const e=novo(),antes=JSON.stringify(e);assert.throws(()=>executar(e,e.seres.icaro,'inventar_recurso'),/Ação inválida/);assert.equal(JSON.stringify(e),antes)});
await t('estoque zerado não oferece coleta e peixes zerados não renascem',()=>{const e=novo();e.seres.icaro.local='rio';e.mundo.ecossistema.agua.nascente=0;e.mundo.ecossistema.peixes.rio.populacao=0;assert(!acoes(e,e.seres.icaro).some(a=>a.id==='pescar'));const b=e.mundo.ecossistema.agua.nascente;regenerar(e.mundo,{chuva:'seco',frutificacao:false,reproducaoPeixes:true,regeneracaoVegetal:false});assert.equal(e.mundo.ecossistema.agua.nascente,b);assert.equal(e.mundo.ecossistema.peixes.rio.populacao,0)});
await t('calendário avança períodos e estações uma vez',()=>{const e=novo();e.mundo.tempo.ciclo=179;e.mundo.tempo=require('./calendario').tempoDe(179);const ev=avancar(e.mundo);assert.equal(e.mundo.tempo.ciclo,180);assert.equal(e.mundo.tempo.estacao,'transicao_umida');assert(ev.frutificacao)});
await t('regeneração climática respeita capacidades e estoques existentes',()=>{const ec=require('./ecossistema'),e=novo(),m=e.mundo,b=m.ecossistema.agua.fontes.nascente.nivel;ec.atualizarMundo(e);assert(m.ecossistema.agua.fontes.nascente.nivel>b);assert(Object.values(m.ecossistema.arvores).every(a=>a.frutos<=a.capacidadeFrutos));assert(m.ecossistema.peixes.rio.populacao<=m.ecossistema.peixes.rio.capacidade)});
await t('percepção deriva do local e estoque sem revelar números',()=>{const e=novo();e.seres.icaro.local='rio';const p=perceber(e,e.seres.icaro).join(' ');assert(p.includes('rio')&&p.includes('Peixes'));assert(!/\b24\b|estoque/i.test(p))});
await t('observação separa pista percebida de descoberta e evento',()=>{const e=novo(),s=e.seres.icaro;s.local='rio';const p=perceber(e,s);assert(p.length);assert.equal(e.descobertas.length,0);const r=executar(e,s,'observar');assert.deepStrictEqual(r.pistas,p);assert.equal(e.descobertas.length,0)});
await t('estado biológico muda por necessidade real',()=>{const e=novo(),s=e.seres.icaro;s.necessidades.agua=70;require('./seres').atualizar(s,e.mundo,'esperar');assert.equal(s.status,'critico');s.necessidades.agua=100;require('./seres').atualizar(s,e.mundo,'esperar');assert.equal(s.status,'morto')});
await t('falha do decisor deixa ciclo sem avançar ou persistir',async()=>{const d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-fail-')),e=novo(),f=path.join(d,'estado.json'),l=path.join(d,'log.jsonl');gravar(f,e);await assert.rejects(executarCiclos(1,{estado:e,arquivoEstado:f,arquivoLog:l,decisor:async()=>{throw Error('offline')}}),/Decisor indisponível/);assert.equal(carregar(f).mundo.tempo.ciclo,e.mundo.tempo.ciclo);assert(!fs.existsSync(l));fs.rmSync(d,{recursive:true,force:true})});
await t('ciclo integrado, interrupção, retomada e sem duplicação',async()=>{const d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-resume-')),f=path.join(d,'estado.json'),l=path.join(d,'logs','ciclos.jsonl'),e=novo(),pick=async(c,a)=>({acao:a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'observar pista'});gravar(f,e);await executarCiclos(2,{estado:carregar(f),arquivoEstado:f,arquivoLog:l,decisor:pick});const retomado=carregar(f),c=retomado.mundo.tempo.ciclo;await executarCiclos(2,{estado:retomado,arquivoEstado:f,arquivoLog:l,decisor:pick});const final=carregar(f),linhas=fs.readFileSync(l,'utf8').trim().split('\n').map(JSON.parse);assert.equal(final.mundo.tempo.ciclo,c+2);assert.equal(linhas.length,16);assert.equal(new Set(linhas.map(x=>x.ciclo)).size,4);assert(!('estadoAntes'in linhas[0]));fs.rmSync(d,{recursive:true,force:true})});
await t('mundo prepara fontes distintas, Maria, João e Lara com necessidades e vínculos',()=>{const e=require('./ecossistema').preparar(novo());assert.deepStrictEqual(Object.keys(e.seres).sort(),['icaro','joao','lara','maria']);assert(e.mundo.ecossistema.agua.fontes.lago.nivel>0);assert(e.mundo.ecossistema.agua.fontes.nascente);assert.equal(e.relacoes.maria.joao,50);assert(e.relacoes.lara.icaro>0,'irmãos já se conhecem');assert(Array.isArray(e.mundo.ecossistema.fauna.aves.individuos))});
await t('fauna individual envelhece e população de peixes zerada não reaparece',()=>{const ec=require('./ecossistema'),e=ec.preparar(novo()),f=e.mundo.ecossistema.fauna.aves,idade=f.individuos[0].idade;e.mundo.ecossistema.fauna.peixes.populacao=0;e.mundo.ecossistema.peixes.rio.populacao=0;ec.atualizarMundo(e);assert(f.individuos[0].idade>idade);assert.equal(e.mundo.ecossistema.fauna.peixes.populacao,0)});
await t('Maria e João decidem pelo próprio cérebro e retêm experiência',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo()),m=e.seres.maria;m.necessidades.solidao=90;m.necessidades.agua=0;m.necessidades.alimento=0;m.necessidades.sono=0;m.necessidades.energia=80;const before=e.relacoes.maria.icaro;const sociavel=async(c,a)=>({acao:a.some(x=>x.id==='conviver')?'conviver':a[0].id,motivo:'escolha do próprio cérebro',origem:'stub'});await rodada(e,{decisor:sociavel});assert(e.relacoes.maria.icaro>before);assert(m.memoria.some(x=>x.tipo==='social'));assert(m.necessidades.solidao<90,'solidão alta não pode virar regra: mas conviver a socorreu');const p=e.mundo.ecossistema.fauna.peixes;p.populacao=10;for(const a of Object.values(e.mundo.ecossistema.arvores))a.frutos=0;m.local='rio';m.inventario.alimento=0;m.necessidades.alimento=0;const pescador=async(c,a)=>({acao:a.some(x=>x.id==='pescar')?'pescar':a[0].id,motivo:'quer pescar',origem:'stub'});await rodada(e,{decisor:pescador});assert(m.experiencia.some(x=>x.includes('pescar')));assert(m.cortex.diario.length>0,'diário de bordo registra o vivido')});
await t('ecossistema e seres ativos continuam após a morte de Ícaro',async()=>{const d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-mundo-continua-')),f=path.join(d,'estado.json'),l=path.join(d,'ciclos.jsonl'),e=require('./ecossistema').preparar(novo());e.seres.icaro.status='morto';const c=e.mundo.tempo.ciclo;gravar(f,e);const final=await executarCiclos(3,{estado:carregar(f),arquivoEstado:f,arquivoLog:l,decisor:async(c,a,ser)=>{assert.notEqual(ser.id,'icaro','morte não pode decidir');return{acao:'observar',motivo:'mundo segue',origem:'stub'}}});assert.equal(final.mundo.tempo.ciclo,c+3);assert.equal(final.seres.icaro.status,'morto');assert(final.seres.maria.experiencia.length>0&&final.seres.joao.experiencia.length>0);assert.equal(fs.readFileSync(l,'utf8').trim().split('\n').length,9);fs.rmSync(d,{recursive:true,force:true})});
await t('experimento de trajetória executa ciclos longos em braços isolados',async()=>{const x=await require('./experimento-trajetoria').executarExperimento({ciclos:240});assert.equal(x.controle.ciclosSolicitados,240);assert.equal(x.acumulada.ciclosSolicitados,240);assert.equal(x.controle.ciclosExecutados,240);assert.equal(x.acumulada.ciclosExecutados,240);assert.deepStrictEqual(x.comparacao.frequenciaAcoes.controle,x.comparacao.frequenciaAcoes.acumulada);assert(x.comparacao.observacao.includes('não demonstra aprendizagem'));console.log('ANÁLISE TRAJETÓRIA '+JSON.stringify({ciclos:[x.controle.ciclosExecutados,x.acumulada.ciclosExecutados],frequência:x.comparacao.frequenciaAcoes,diferenças:{peixes:x.comparacao.diferencaPeixes,lago:x.comparacao.diferencaLago},memórias:x.comparacao.memoriasAcumuladas,status:[x.controle.resultado.seres.icaro.status,x.acumulada.resultado.seres.icaro.status]}))});
await t('controle de memória bloqueia contexto e braço acumulado o fornece',async()=>{const decisor=async(c,a)=>({acao:c.memorias.length?'observar':'descansar',motivo:'prova de acesso ao contexto'}),x=await require('./experimento-trajetoria').executarExperimento({ciclos:24,decisor});assert(x.acumulada.acoes.observar>(x.controle.acoes.observar||0));assert(x.controle.acoes.descansar>x.acumulada.acoes.descansar)});
await t('espaço: locais conectados por trilhas, sem teletransporte no grafo',()=>{const espaco=require('./espaco');assert(Object.keys(espaco.nos).length>=12);const r=espaco.rota('casa_joao','rio');assert(r&&r.caminho[0]==='casa_joao'&&r.caminho[r.caminho.length-1]==='rio','existe rota casa_joao→rio');assert(r.caminho.length>=3,'a rota exige trechos intermediários');assert(r.trechos.every(t=>t.linha.length>=2),'cada trecho tem polilinha de trilha');assert.equal(espaco.rota('rio','rio').caminho.length,1);assert.strictEqual(espaco.rota('casa_icaro','ilha_inexistente'),null);assert.equal(espaco.normalizar('pesca_mar'),'mar','alias legado do mar')});
await t('deslocamento: decisão de ir vira trajeto de 1 trecho por ciclo; cérebro só consulta na partida e na chegada',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo()),s=e.seres.icaro;s.local='casa_joao';let consultas=0;const decisor=async(c,a,ser)=>{if(ser.id==='icaro'){consultas++;if(a.some(x=>x.id==='ir_rio'))return{acao:'ir_rio',motivo:'quer ir pescar no rio',origem:'stub'}}return{acao:'esperar',motivo:'aguarda',origem:'stub'}};await rodada(e,{decisor});assert(s.deslocamento,'trajeto iniciado');assert.equal(s.local,'casa_joao','não teleportou no mesmo ciclo');const comprimento=s.deslocamento.caminho.length;let ciclos=1;while(s.deslocamento&&ciclos<15){await rodada(e,{decisor});ciclos++}assert.equal(s.local,'rio','chegou ao destino pelo caminho');assert(!s.deslocamento,'deslocamento terminou na chegada');assert.equal(ciclos,comprimento,'1 ciclo por trecho (partida + avanços)');assert.equal(consultas,2,'cérebro consultado só na partida e na chegada — não a cada passo');assert(acoes(e,s).some(a=>a.id==='pescar'),'ações do rio disponíveis só após chegar');assert(e.historico.eventos.some(x=>x.tipo==='deslocamento'&&x.fase==='chegada'),'linha do tempo registra a chegada');assert(e.historico.decisoes.length>0,'decisões registradas na linha do tempo')});
await t('deslocamento: cérebro reroteia; ação local cancela o trajeto; continuar exige trajeto',()=>{const ec=require('./ecossistema'),e=ec.preparar(novo()),s=e.seres.icaro;s.local='casa_joao';executar(e,s,'ir_floresta');assert(s.deslocamento&&s.deslocamento.destino==='floresta','trajeto para floresta');const perm=acoes(e,s);assert(perm.some(a=>a.id==='continuar'),'continuar disponível em trajeto');assert(perm.some(a=>a.id==='ir_casa'),'reroteio disponível em trajeto');executar(e,s,'ir_casa');assert.equal(s.deslocamento.destino,s.casa,'reroteou no meio do caminho');executar(e,s,'observar');assert(!s.deslocamento,'ação local assumiu o controle e cancelou o trajeto');assert.throws(()=>executar(e,s,'continuar'),/inválida/,'continuar fora de trajeto não existe')});
await t('acontecimentos: desligados por padrão — mundo não gera eventos nem muda o clima',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo());await rodada(e,{decisor:async()=>({acao:'observar',motivo:'sem eventos',origem:'stub'})});assert(!e.mundo.acontecimentos,'flag off: nenhum evento gerado');assert(!e.historico.eventos.some(x=>x.tipo==='acontecimento'),'nenhuma linha de acontecimento na timeline')});
await t('acontecimentos: predador fere quem está na região; sair do alcance protege; pistas chegam ao cérebro',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo()),s=e.seres.icaro;s.local='bosque';s.necessidades.saude=100;e.mundo.acontecimentos=[{id:'p-teste',tipo:'predador',origem:'mundo',locais:['bosque'],duracao:4,idade:0,ataque:true,pistas:['Rugidos abafados ecoam pela região.']}];let visto=null;const decisor=async(c,a,ser)=>{if(ser.id==='icaro')visto=c;return{acao:a.some(x=>x.id==='ir_rio')?'ir_rio':a[0].id,motivo:'foge do perigo',origem:'stub'}};await rodada(e,{decisor});const ferido=s.necessidades.saude;assert(ferido<100&&ferido>=80,'ataque real: dano de 10–19, sem morte instantânea');assert(visto&&Array.isArray(visto.acontecimentos)&&visto.acontecimentos.length>0,'cérebro recebeu pistas indiretas do evento');assert(s.deslocamento&&s.deslocamento.destino==='rio','sofrendo ataque, o cérebro decide fugir');await rodada(e,{decisor});assert.notEqual(s.local,'bosque','saiu da região em um trecho');assert(s.necessidades.saude>=ferido,'fora do alcance: sem novo dano');let guarda=0;while(e.mundo.acontecimentos.length&&guarda++<10){await rodada(e,{decisor});assert(s.necessidades.saude>=ferido,'nenhum dano fora da região do evento')}});
await t('acontecimentos: tempestade dita chuva_forte durante a duração e expira de volta ao calendário',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo());e.mundo.acontecimentos=[{id:'t-teste',tipo:'tempestade',origem:'mundo',locais:['rio'],duracao:2,idade:0,efeitoClima:'chuva_forte',vento:.9,pistas:['O céu escurece e trovões rolam.']}];const decisor=async()=>({acao:'observar',motivo:'aguarda a chuva passar',origem:'stub'});await rodada(e,{decisor});assert.equal(e.mundo.clima,'chuva_forte','tempestade dita o clima do ciclo');await rodada(e,{decisor});assert.equal(e.mundo.clima,'chuva_forte','segundo ciclo sob tempestade');await rodada(e,{decisor});assert.equal((e.mundo.acontecimentos||[]).length,0,'evento expirou após a duração');assert.notEqual(e.mundo.clima,'chuva_forte','calendário volta a mandar no clima');assert(e.historico.eventos.some(x=>x.tipo==='acontecimento'&&x.fase==='comecou')&&e.historico.eventos.some(x=>x.tipo==='acontecimento'&&x.fase==='terminou'),'timeline registra nascimento e fim do evento')});
await t('observador novo: servidor somente-leitura serve mapa, estado e página',async()=>{const obs=require('./observador-ilha'),http=require('http');const{porta,fechar}=await obs.servir(0);const get=p=>new Promise((ok,fal)=>{http.get({host:'127.0.0.1',port:porta,path:p},r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>ok({status:r.statusCode,body:d}))}).on('error',fal)});try{const m=JSON.parse((await get('/api/mapa')).body);assert.equal(Object.keys(m.nos).length,12,'12 locais no grafo');assert(m.arestas.every(a=>Array.isArray(a.linha)&&a.linha.length>=2),'trilhas com polilinha');const e=await get('/api/estado');assert.equal(e.status,200);JSON.parse(e.body);const pg=await get('/');assert.equal(pg.status,200);assert(pg.body.includes('três verdades'),'página do observador servida');const perc=await get('/api/percepcao?ser=icaro');assert.equal(perc.status,200);JSON.parse(perc.body)}finally{await fechar()}});
await t('FASE B: contrato rejeita decisão inválida sem tocar no estado',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo());e.seres.icaro.local='rio';const antes=JSON.stringify(e);await assert.rejects(rodada(e,{decisor:async()=>({acao:'inventar_recurso',motivo:'fora do contrato',origem:'stub'})}),/Decisão inválida de icaro: ação fora das possíveis/);assert.equal(JSON.stringify(e),antes,'estado intacto após decisão inválida');await assert.rejects(rodada(e,{decisor:async()=>({acao:'observar',origem:'stub'})}),/Decisão inválida de icaro: sem motivo/);assert.equal(JSON.stringify(e),antes,'estado intacto após decisão sem motivo')});
await t('FASE B: cérebros independentes por personagem, cada um com o próprio contexto',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo());e.seres.icaro.local='rio';e.seres.maria.local='bosque';e.seres.joao.local='casa_joao';const alvo={icaro:'pescar',maria:'observar',joao:'descansar',lara:'esperar'},visto={},cerebros={};for(const id of Object.keys(alvo)){cerebros[id]=async(c,a)=>{visto[id]=c;return{acao:a.some(x=>x.id===alvo[id])?alvo[id]:a[0].id,motivo:'decisão própria de '+id,origem:'cérebro-'+id}}}const r=await rodada(e,{cerebros});const origens=Object.fromEntries(r.eventos.map(ev=>[ev.serId,ev.decisao.origem]));assert.equal(origens.icaro,'cérebro-icaro');assert.equal(origens.maria,'cérebro-maria');assert.equal(origens.joao,'cérebro-joao','cada ser foi decidido pelo próprio cérebro');assert.equal(origens.lara,'cérebro-lara');assert(visto.icaro.local==='rio'&&visto.maria.local==='bosque'&&visto.joao.local==='casa_joao'&&visto.lara.local==='acampamento','contexto individual por ser');assert(visto.icaro.acoesPossiveis.some(x=>x.id==='pescar')&&visto.joao.acoesPossiveis.some(x=>x.id==='descansar'),'ações calculadas para o local de cada um');assert.strictEqual(visto.icaro.relacoes,e.relacoes.icaro,'relações: linha do próprio ser, nunca a matriz inteira')});
await t('FASE B: contexto vê só pistas da própria situação — verdade do evento não vaza',()=>{const ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),e=ec.preparar(novo());const ev={id:'p-teste-vasamento',tipo:'predador',origem:'mundo',locais:['floresta'],duracao:4,idade:0,ataque:true,pistas:['Rugidos abafados ecoam pela região.']};e.mundo.acontecimentos=[ev];e.seres.icaro.local='floresta';const dentro=montarContexto(e,e.seres.icaro,acoes(e,e.seres.icaro),ev);assert(dentro.acontecimentos.includes('Rugidos abafados ecoam pela região.'),'pistas indiretas chegam ao cérebro');const dump=JSON.stringify(dentro);assert(!dump.includes('p-teste-vasamento')&&!dump.includes('"locais"')&&!dump.includes('"ataque":true')&&!dump.includes('"duracao":4'),'id, locais, alvo e duração do evento não vaza');assert(typeof dentro.relacoes.maria==='number','relações da linha própria são valores, não objetos alheios');e.seres.maria.local='casa_maria';e.seres.joao.local='casa_maria';const fora=montarContexto(e,e.seres.maria,[]);assert.equal(fora.acontecimentos.length,0,'sem situação percebida não há pistas');assert.equal(fora.pessoasPorPerto.length,1);assert.deepStrictEqual(Object.keys(fora.pessoasPorPerto[0]).sort(),['id','nome'],'vizinho vira só fato: id e nome, sem corpo alheio')});
await t('FASE C: contexto entrega só memória/conhecimento do próprio personagem — o global fica no mundo',()=>{const ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),e=ec.preparar(novo());e.memorias.push({texto:'OBSERVACAO-DE-TERCEIROS'});e.descobertas.push('DESCOBERTA-GLOBAL');e.seres.maria.memoria.push({texto:'MEMORIA-PROPRIA-DA-MARIA'});const ctx=montarContexto(e,e.seres.icaro,[]);const dump=JSON.stringify(ctx);assert(!dump.includes('OBSERVACAO-DE-TERCEIROS'),'memória global legada não vira conhecimento do personagem');assert(!dump.includes('DESCOBERTA-GLOBAL'),'descoberta global não vaza');assert(!dump.includes('MEMORIA-PROPRIA-DA-MARIA'),'memória da Maria não vaza para o Ícaro');e.seres.icaro.memoria.push({texto:'MEMORIA-PROPRIA-DO-ICARO'});const ctx2=montarContexto(e,e.seres.icaro,[]);assert(ctx2.memorias.some(t=>t.includes('MEMORIA-PROPRIA-DO-ICARO')),'memória individual entregue');const cx=ctx2.cortex||{};assert(cx.identidade&&cx.identidade.nome,'cortex: identidade');assert(Array.isArray(cx.conhecimentos),'cortex: conhecimentos');assert(Array.isArray(cx.objetivos)&&Array.isArray(cx.trajetoriaRecente)&&Array.isArray(cx.diario)&&Array.isArray(cx.memoria),'cortex: objetivos, trajetória recente, diário e memória entregues')});
await t('FASE D: três instâncias independentes de CharacterBrain — cada um com contexto, decisão e estado próprios',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo()),ic=e.seres.icaro,ma=e.seres.maria,jo=e.seres.joao;ic.local='rio';ma.local='bosque';jo.local='casa_joao';ic.necessidades.agua=85;ma.necessidades.agua=12;jo.necessidades.sono=80;ic.memoria.push({ciclo:1,texto:'MEM-ICARO vi o rio transbordar',tipo:'ambiente'});ma.memoria.push({ciclo:1,texto:'MEM-MARIA achou frutos maduros',tipo:'ambiente'});jo.memoria.push({ciclo:1,texto:'MEM-JOAO ouviu a fogueira crepitar',tipo:'ambiente'});e.relacoes.icaro.maria=61;e.relacoes.maria.icaro=62;e.relacoes.joao.icaro=63;const visto={};const mk=(id,alvo)=>criarCerebro({id,escolher:(c,a)=>{visto[id]={local:c.local,necessidades:{...c.necessidades},memorias:[...c.memorias],percepcoes:[...c.percepcoes],relacoes:{...c.relacoes},relRef:c.relacoes,pessoasPorPerto:[...c.pessoasPorPerto]};return{acao:a.some(x=>x.id===alvo)?alvo:a[0].id,motivo:'decisão de '+id+' em '+c.local}}});const bIc=mk('icaro','pescar'),bMa=mk('maria','colher_frutas'),bJo=mk('joao','descansar'),bLa=mk('lara','esperar');assert.notStrictEqual(bIc,bMa);assert.notStrictEqual(bMa,bJo);assert.notStrictEqual(bIc.decidir,bMa.decidir,'funções distintas: não é um cérebro único servindo três');assert.equal(new Set([bIc.instancia,bMa.instancia,bJo.instancia,bLa.instancia]).size,4,'quatro instâncias numeradas');const r=await rodada(e,{cerebros:{icaro:bIc,maria:bMa,joao:bJo,lara:bLa},decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO neste teste')}});assert.equal(r.eventos.length,4,'os quatro decidiram pelos próprios cérebros');const origens=Object.fromEntries(r.eventos.map(x=>[x.serId,x.decisao.origem]));assert.equal(origens.icaro,'cérebro-icaro');assert.equal(origens.maria,'cérebro-maria');assert.equal(origens.joao,'cérebro-joao');assert.equal(origens.lara,'cérebro-lara');assert.equal(new Set(r.eventos.map(x=>x.decisao.acao)).size,4,'quatro decisões diferentes');assert.equal(visto.icaro.local,'rio');assert.equal(visto.maria.local,'bosque');assert.equal(visto.joao.local,'casa_joao','localização própria, sem vazamento');assert.equal(visto.icaro.necessidades.agua,85);assert.equal(visto.maria.necessidades.agua,12,'corpo alheio não vaza');assert.equal(visto.joao.necessidades.sono,80);assert(visto.icaro.memorias.some(t=>t.includes('MEM-ICARO'))&&!visto.icaro.memorias.some(t=>t.includes('MEM-MARIA'))&&!visto.icaro.memorias.some(t=>t.includes('MEM-JOAO')),'memória só do próprio ser');assert(visto.maria.memorias.some(t=>t.includes('MEM-MARIA'))&&!visto.maria.memorias.some(t=>t.includes('MEM-ICARO')),'memória da Maria só dela');assert(visto.joao.memorias.some(t=>t.includes('MEM-JOAO'))&&!visto.joao.memorias.some(t=>t.includes('MEM-MARIA')),'memória do João só dele');const pIc=visto.icaro.percepcoes.join(' '),pMa=visto.maria.percepcoes.join(' '),pJo=visto.joao.percepcoes.join(' ');assert(pIc.includes('rio')&&!pIc.includes('Aves cruzam o bosque')&&!pIc.includes('Árvores frutíferas'),'percepção do rio, não a dos outros');assert(pMa.includes('bosque')&&!pMa.includes('O rio está visível.'),'percepção do bosque, não a do rio');assert(!pJo.includes('O rio está visível.')&&!pJo.includes('Árvores frutíferas'),'percepção da casa, sem os outros locais');assert.strictEqual(visto.icaro.relRef,e.relacoes.icaro,'relações: linha do próprio ser');assert.notStrictEqual(visto.icaro.relRef,visto.maria.relRef,'linhas distintas por ser');assert.equal(visto.icaro.relacoes.maria,61);assert.equal(visto.maria.relacoes.icaro,62);assert.equal(visto.joao.relacoes.icaro,63,'vínculos próprios chegaram inteiros');assert.equal(visto.icaro.pessoasPorPerto.length,0,'ninguém no rio: sem gente alheia no contexto');assert.equal(bIc.interno.decisoes,1);assert.equal(bMa.interno.decisoes,1);assert.equal(bJo.interno.decisoes,1);assert.equal(bLa.interno.decisoes,1,'uma decisão por instância: nada de reuso');assert.equal(bIc.interno.ultimoContexto.local,'rio');assert.notStrictEqual(bIc.interno.ultimoContexto,bMa.interno.ultimoContexto,'estado interno não compartilhado');bIc.interno.prova='so-icaro';assert(!('prova'in bMa.interno)&&!('prova'in bJo.interno),'mutação num cérebro não atinge os outros')});
await t('FASE D: ciclo completo A→cérebro A, B→…, C→… até consequência e experiência, sem decisor legado',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo());e.seres.icaro.local='rio';e.seres.maria.local='bosque';e.seres.joao.local='casa_joao';const brains={icaro:criarCerebro({id:'icaro',escolher:(c,a)=>({acao:a.some(x=>x.id==='pescar')?'pescar':a[0].id,motivo:'os peixes estão aqui'})}),maria:criarCerebro({id:'maria',escolher:(c,a)=>({acao:a.some(x=>x.id==='colher_frutas')?'colher_frutas':a[0].id,motivo:'vi frutos maduros'})}),joao:criarCerebro({id:'joao',escolher:(c,a)=>({acao:a.some(x=>x.id==='descansar')?'descansar':a[0].id,motivo:'vou descansar em casa'})}),lara:criarCerebro({id:'lara',escolher:(c,a)=>({acao:a.some(x=>x.id==='descansar')?'descansar':a[0].id,motivo:'descansa no acampamento'})})};const alimentoAntes=e.seres.maria.inventario.alimento;const r=await rodada(e,{cerebros:brains,decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO neste teste')}});assert.equal(r.eventos.length,4);const porSer=Object.fromEntries(r.eventos.map(x=>[x.serId,x.decisao]));assert.equal(porSer.icaro.origem,'cérebro-icaro');assert.equal(porSer.maria.origem,'cérebro-maria');assert.equal(porSer.joao.origem,'cérebro-joao','validação preservou a decisão de cada um');assert.equal(porSer.lara.origem,'cérebro-lara');assert(r.eventos.find(x=>x.serId==='maria').consequencia.quantidade>0,'motor calculou a consequência da colheita');assert(e.seres.maria.inventario.alimento>alimentoAntes,'consequência real no mundo');assert(e.seres.icaro.experiencia.some(x=>x.includes('pescar'))&&!e.seres.icaro.experiencia.some(x=>x.includes('colher_frutas')),'experiência individual, sem mistura');assert(e.seres.maria.experiencia.some(x=>x.includes('colher_frutas')));assert(e.seres.joao.experiencia.some(x=>x.includes('descansar')));assert(e.seres.maria.cortex.diario.some(d=>d.acao==='colher_frutas')&&!e.seres.maria.cortex.diario.some(d=>d.acao==='pescar'),'diário próprio registra a própria ação');assert.equal(brains.icaro.interno.decisoes,1)&&assert.equal(brains.maria.interno.decisoes,1)&&assert.equal(brains.joao.interno.decisoes,1)&&assert.equal(brains.lara.interno.decisoes,1)});
await t('FASE D: instância presa ao personagem — o cérebro da Maria recusa servir o Ícaro',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo());const bMa=criarCerebro({id:'maria',escolher:()=>({acao:'esperar',motivo:'ok'})});await assert.rejects(rodada(e,{cerebros:{icaro:bMa},decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO')}}),/CharacterBrain maria recebeu contexto de icaro/)});
await t('FASE D: adaptador do cérebro novo — mapeia contexto a fatos e recusa conexão ainda não existente',()=>{const ad=require('./adaptador-cerebro-icaro'),ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),e=ec.preparar(novo());e.seres.icaro.local='rio';const m=ad.mapearContextoParaIcaro(montarContexto(e,e.seres.icaro,[]));assert(Array.isArray(m.fatos)&&m.fatos.length>0);assert(m.fatos.some(f=>f.includes('rio')),'fatos derivados do próprio contexto');assert(m.fatos.every(f=>typeof f==='string'));assert(!m.fatos.some(f=>/precisa beber|deve fugir|v[áa] para|fa[çc]a a miss[ãa]o/i.test(f)),'só fatos, nunca ordens');assert.throws(()=>ad.decidir(),err=>err.decisao===true&&/não está conectado/.test(err.message),'falha honesta, marcada como decisão');assert.equal(ad.CONEXAO_NAO_FEITA,true,'sem fingir integração')});
await t('FASE G: conviver grava memória social dos DOIS lados e o vínculo muda no próximo contexto',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{montarContexto,criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo());e.seres.icaro.local='casa_icaro';e.seres.maria.local='casa_icaro';e.seres.joao.local='casa_joao';const antesIc=e.relacoes.icaro.maria,antesMa=e.relacoes.maria.icaro;const mk=id=>criarCerebro({id,escolher:(c,a)=>({acao:a.some(x=>x.id==='conviver')?'conviver':a[0].id,motivo:'quer conversar'})}),jo=criarCerebro({id:'joao',escolher:()=>({acao:'esperar',motivo:'em casa'})}),la=criarCerebro({id:'lara',escolher:()=>({acao:'esperar',motivo:'no acampamento'})});await rodada(e,{cerebros:{icaro:mk('icaro'),maria:mk('maria'),joao:jo,lara:la},decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO neste teste')}});assert(e.seres.icaro.memoria.some(m=>m.tipo==='social'&&m.texto.includes('conversou com você')),'o presente registrou a conversa para o Ícaro');assert(e.seres.maria.memoria.some(m=>m.tipo==='social'&&m.texto.includes('conversou com você')),'e para a Maria');assert(e.seres.icaro.memoria.some(m=>m.tipo==='social'&&m.texto.startsWith('Conversou com')),'o ativo lembra da própria conversa');assert(e.relacoes.icaro.maria>antesIc&&e.relacoes.maria.icaro>antesMa,'vínculo subiu nos dois lados');const ctx=montarContexto(e,e.seres.icaro,[]);assert.equal(ctx.relacoes.maria,e.relacoes.icaro.maria,'próximo contexto entrega o vínculo atualizado');assert(ctx.memorias.some(t=>t.includes('conversou com você')),'memória social chega ao próximo contexto')});
await t('FASE G: falar — o falante guarda memória própria e os dois vínculos aproximam',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{montarContexto,criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo());e.seres.icaro.local='casa_icaro';e.seres.maria.local='casa_icaro';e.seres.joao.local='casa_joao';const antes={eu:e.relacoes.icaro.maria,ela:e.relacoes.maria.icaro};const b={icaro:criarCerebro({id:'icaro',escolher:(c,a)=>({acao:a.some(x=>x.id==='falar')?'falar':a[0].id,motivo:'quer contar uma ideia'})}),maria:criarCerebro({id:'maria',escolher:()=>({acao:'esperar',motivo:'escuta'})}),joao:criarCerebro({id:'joao',escolher:()=>({acao:'esperar',motivo:'em casa'})}),lara:criarCerebro({id:'lara',escolher:()=>({acao:'observar',motivo:'olha o acampamento'})})};await rodada(e,{cerebros:b,decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO neste teste')}});assert(e.relacoes.icaro.maria>antes.eu,'vínculo do falante subiu');assert(e.relacoes.maria.icaro>antes.ela,'vínculo do ouvinte subiu');assert(e.seres.icaro.memoria.some(m=>m.tipo==='social'&&m.texto.includes('Falou com')),'o falante lembra que falou');assert(e.seres.maria.memoria.some(m=>m.tipo==='fala'&&m.de==='icaro'),'o ouvinte registrou a fala');const ctx=montarContexto(e,e.seres.icaro,[]);assert(ctx.memorias.some(t=>t.includes('Falou com')),'memória da fala chega ao próximo contexto do falante')});
await t('ILHA AURORA: identidade, personalidade e história iniciais próprias dos quatro, entregues ao cérebro como contexto',()=>{const ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),e=ec.preparar(novo());const ids=['icaro','maria','joao','lara'];assert(ids.every(id=>Array.isArray(e.seres[id].personalidade)&&e.seres[id].personalidade.length>=4),'os quatro nascem com traços de personalidade');assert.equal(new Set(ids.map(id=>JSON.stringify(e.seres[id].personalidade))).size,4,'as personalidades são diferentes');assert(e.seres.maria.personalidade.includes('corajosa')&&!e.seres.joao.personalidade.includes('corajosa'),'Maria é corajosa; João não');assert(e.seres.joao.personalidade.includes('protetor')&&!e.seres.icaro.personalidade.includes('protetor'),'João é protetor; Ícaro não');assert(e.seres.icaro.personalidade.includes('curioso')&&!e.seres.maria.personalidade.includes('curioso'),'Ícaro é curioso; Maria não');assert.equal(new Set(ids.map(id=>e.seres[id].cortex.biografia.passado)).size,4,'histórias prévias distintas, não cópias');assert(ids.every(id=>e.seres[id].cortex.biografia.passado!=='Iniciou sua trajetória na ilha.'),'história prévia real, não a semente padrão');assert(ids.every(id=>e.seres[id].historia&&e.seres[id].historia.lembrancas.length>0&&e.seres[id].historia.habilidades.every(h=>h.texto&&h.origem)&&e.seres[id].historia.pertences.length>0),'história com lembranças, habilidades de origem declarada e pertences');const ctxJ=montarContexto(e,e.seres.joao,[]),ctxM=montarContexto(e,e.seres.maria,[]),ctxI=montarContexto(e,e.seres.icaro,[]),ctxL=montarContexto(e,e.seres.lara,[]);for(const ctx of [ctxJ,ctxM,ctxI,ctxL]){assert.equal(ctx.ilha,'Ilha Aurora','sabem onde vivem: a ilha');assert(ctx.cortex.conhecimentos.some(c=>c.includes('Ilha Aurora')),'conhecimento próprio da ilha');assert(Array.isArray(ctx.personalidade)&&ctx.personalidade.length>=4,'traços chegam ao cérebro como contexto');assert(ctx.cortex.identidade&&ctx.cortex.identidade.nome,'sabem quem são: identidade');assert(ctx.cortex.passado&&ctx.cortex.passado!=='Iniciou sua trajetória na ilha.','sabem quem foram: passado próprio')}assert.equal(ctxJ.historia.residencia,'casa_joao');assert.equal(ctxM.historia.residencia,'casa_joao','Maria mora com o marido, na mesma casa');assert.equal(ctxI.historia.residencia,'casa_icaro');assert.equal(ctxL.historia.residencia,'casa_icaro','cada um sabe onde mora');assert(new Set([ctxJ.historia.ocupacao,ctxM.historia.ocupacao,ctxI.historia.ocupacao,ctxL.historia.ocupacao]).size===4,'ocupações próprias');assert(/esposa/.test(ctxJ.historicoRelacoes.maria.texto),'João sabe que Maria é sua esposa');assert(/marido/.test(ctxM.historicoRelacoes.joao.texto),'Maria sabe que João é seu marido');assert(ctxI.historicoRelacoes.joao&&ctxI.historicoRelacoes.maria,'Ícaro conhece os dois');assert(ctxI.historicoRelacoes.lara&&ctxL.historicoRelacoes.icaro&&/irmã/.test(ctxL.historicoRelacoes.icaro.texto),'Ícaro e Lara se conhecem como irmãos');assert(ctxJ.historia.habilidades.length>0&&ctxM.historia.pertences.length>0&&ctxI.historia.lembrancas.length>0&&ctxL.historia.lembrancas.length>0,'habilidades, pertences e lembranhas no contexto')});
await t('ILHA AURORA: personalidade não vira regra — mesma situação, decisões diferentes, todas do próprio cérebro',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo());e.seres.icaro.local='bosque';e.seres.maria.local='bosque';e.seres.joao.local='bosque';e.seres.lara.local='bosque';e.mundo.acontecimentos=[{id:'p-aurora',tipo:'predador',origem:'mundo',locais:['bosque'],duracao:4,idade:0,ataque:true,pistas:['Rugidos abafados ecoam pela região.']}];assert(e.seres.maria.personalidade.includes('corajosa'),'Maria começa corajosa (traço, não comando)');const mk=(id,d)=>criarCerebro({id,escolher:(c,a)=>({acao:a.some(x=>x.id===d)?d:a[0].id,motivo:'decisão de '+id+' na mesma situação'})});const r=await rodada(e,{cerebros:{icaro:mk('icaro','ir_rio'),maria:mk('maria','observar'),joao:mk('joao','ir_casa'),lara:mk('lara','descansar')},decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO neste teste')}});assert.equal(r.eventos.length,4,'os quatro decidiram');const acoes4=r.eventos.map(x=>x.decisao.acao);assert.equal(new Set(acoes4).size,4,'mesma situação, quatro decisões diferentes');assert(r.eventos.every(x=>x.decisao.origem.startsWith('cérebro-')),'todas vieram dos próprios cérebros — nenhuma ação injetada por regra de traço');assert(acoes4.includes('observar')&&acoes4.includes('ir_rio')&&acoes4.includes('ir_casa')&&acoes4.includes('descansar'),'a corajosa observou em vez de enfrentar: o traço não obrigou nada');assert(e.seres.maria.necessidades.saude<100&&e.seres.maria.status!=='morto','perigo real existe, mas a escolha continua do cérebro')});
await t('ILHA AURORA: futuro aberto — nada decidido antes; o sistema não reescreve identidade; experiência vira trajetória',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{montarContexto}=require('./cerebro-personagem'),e=ec.preparar(novo());const ids=['icaro','maria','joao','lara'];const snap=()=>JSON.stringify(ids.map(id=>({p:e.seres[id].personalidade,h:e.seres[id].historia,pass:e.seres[id].cortex.biografia,rel:JSON.parse(JSON.stringify(e.relacoesHistoria[id]))})));const antes=snap();const h=e.historico||{decisoes:[]};assert(!h.decisoes||h.decisoes.length===0,'nenhuma decisão futura escrita no estado inicial');const cx=e.seres.joao.cortex;assert.equal(cx.trajetoria.length,0);assert.equal(cx.diario.length,1,'o diário só traz a moradia de ciclo 0, escrita pelo mundo');assert.equal(cx.diario[0].acao,'moradia');assert.equal(cx.diario[0].ciclo,0,'fato passado, não destino futuro');assert.equal(cx.objetivos.length,0,'nenhum objetivo nem destino predeterminado');const stub=async(c,a)=>({acao:a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'vai ver o que acontece',origem:'stub'});for(let i=0;i<3;i++)await rodada(e,{decisor:stub});assert.equal(snap(),antes,'o sistema não reescreve personalidade, história, biografia ou relações iniciais (#14)');assert.equal(e.seres.joao.cortex.trajetoria.length,3,'a trajetória que existe depois é deles, não nossa');assert.equal(e.seres.joao.cortex.diario.filter(d=>d.ciclo>0).length,3,'diário de bordo registra o vivido');assert(e.seres.joao.cortex.diario[0].motivo.includes('Maria'),'a moradia escrita pelo mundo continua lá');const ctx=montarContexto(e,e.seres.joao,[]);assert.equal(ctx.cortex.trajetoriaRecente.length,3,'experiência posterior entra no contexto seguinte (#13)')});
await t('ILHA AURORA: bíblia do mundo corresponde ao mapa de espaco.js, nó a nó',()=>{const espaco=require('./espaco'),{biblia,NOME}=require('./biblia-ilha-aurora');assert.equal(NOME,'Ilha Aurora');const ids=Object.keys(biblia.geografia.locais);assert.equal(ids.length,12,'bíblia cobre os 12 locais');assert.deepStrictEqual([...ids].sort(),Object.keys(espaco.nos).sort(),'mesmos nós do grafo, nem mais nem menos');for(const id of ids)assert.equal(biblia.geografia.locais[id].nome,espaco.nos[id].nome,'nome exato: '+id);assert(biblia.eventosPossiveis.some(ev=>ev.status.includes('futuro')),'o que ainda não existe no motor é marcado, não fingido');assert(biblia.misterios.length>0&&biblia.misterios.every(m=>Array.isArray(m.conhecidoPor)),'mistérios com donos (hoje: ninguém)')});
await t('ILHA AURORA: conhecimento é individual — o que um sabe, o outro não; mistério do mundo não vaza',()=>{const ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),{biblia}=require('./biblia-ilha-aurora'),e=ec.preparar(novo());const ctxJ=montarContexto(e,e.seres.joao,[]),ctxM=montarContexto(e,e.seres.maria,[]),ctxI=montarContexto(e,e.seres.icaro,[]);assert(ctxJ.cortex.conhecimentos.some(c=>c.includes('trilha')),'João conhece a trilha da casa');assert(!JSON.stringify(ctxM).includes('trilha entre a casa'),'o conhecimento do João não vaza para Maria');assert(ctxM.cortex.conhecimentos.some(c=>c.includes('frutos sazonais')),'Maria conhece os frutos sazonais');assert(!JSON.stringify(ctxI).includes('frutos sazonais'),'o conhecimento da Maria não vaza para o Ícaro');assert(ctxI.cortex.conhecimentos.some(c=>c.includes('acampamento até o mar')),'o Ícaro conhece o caminho do acampamento ao mar');const mist=biblia.misterios.map(m=>m.descricao).join(' ');assert(mist&&!JSON.stringify([ctxJ,ctxM,ctxI]).includes(mist.split('.')[0]),'mistério do mundo não vaza a nenhum cérebro');assert(Array.isArray(ctxJ.percepcoes)&&Array.isArray(ctxJ.cortex.conhecimentos)&&ctxJ.percepcoes!==ctxJ.cortex.conhecimentos,'percepção e conhecimento continuam campos distintos')});
await t('ILHA AURORA: crença proposta pelo próprio cérebro fica no proponente e chega ao próximo contexto',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{montarContexto,criarCerebro}=require('./cerebro-personagem'),e=ec.preparar(novo());e.seres.icaro.local='acampamento';e.seres.maria.local='casa_maria';e.seres.joao.local='casa_joao';const b={icaro:criarCerebro({id:'icaro',escolher:(c,a)=>({acao:a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'anota o que observou',crencas:['Cruzar a floresta depois do anoitecer é perigoso.']})}),maria:criarCerebro({id:'maria',escolher:()=>({acao:'esperar',motivo:'em casa'})}),joao:criarCerebro({id:'joao',escolher:()=>({acao:'esperar',motivo:'em casa'})}),lara:criarCerebro({id:'lara',escolher:()=>({acao:'esperar',motivo:'no acampamento'})})};await rodada(e,{cerebros:b,decisor:async()=>{throw Error('DECISOR LEGADO PROIBIDO neste teste')}});assert(e.seres.icaro.cortex.crencas.some(x=>x.texto.includes('Cruzar a floresta')),'crença guardada no cortex de quem refletiu');assert.equal(e.seres.maria.cortex.crencas.length,0,'creança não vaza para os outros');assert.equal(e.seres.joao.cortex.crencas.length,0,'creança não vaza para os outros');const ctx=montarContexto(e,e.seres.icaro,[]);assert(ctx.cortex.crencas.some(x=>x.texto.includes('Cruzar a floresta')),'próximo contexto entrega a crença ao próprio cérebro');assert(!montarContexto(e,e.seres.maria,[]).cortex.crencas.some(x=>x.texto.includes('Cruzar a floresta')),'nunca no contexto alheio')});
await t('M1: a experiência vira turno e diário no formato do ICAROOVO',async()=>{const mem=require('./memoria-personagem'),ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-fmt-'));mem.ativar(d);try{const e=ec.preparar(novo());for(const id of ['icaro','maria','joao'])e.seres[id].local='acampamento';const stub=async(c,a)=>({acao:a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'observa o mundo ao redor',origem:'stub'});await rodada(e,{decisor:stub});for(const id of ['joao','maria','icaro']){const turnos=mem.instanciar(id).chat.carregarTodos();assert(turnos.length>=3,id+': semente + entrada do mundo + a própria ação');assert.equal(turnos[0].quem,'system',id+': identidade é a primeira');assert.equal(turnos[1].quem,'mundo',id+': entrada do mundo');assert.equal(turnos[2].quem,id,id+': a própria ação');assert(turnos.every(x=>x.id&&x.quem&&x.texto&&x.quando),id+': turno no formato {id,quem,texto,quando}');assert(!/Rafael|cortrajetor|trajectoria corticalis/.test(JSON.stringify(turnos)),id+': nada do ICAROOVO no chat');const reg=JSON.parse(fs.readFileSync(path.join(mem.dirDe(id),'diario.jsonl'),'utf8').trim().split('\n').pop());assert.equal(reg.tipo,'experiencia');assert.equal(reg.sessao,id);assert(typeof reg.turno==='number'&&/^\d{4}-\d{2}-\d{2}T/.test(reg.quando));assert(reg.entrada_dono.length>0,'entrada do mundo no diário');assert(reg.resposta_icaro.length>=15,'resposta factual de pelo menos 15 caracteres')}}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M1: papéis — identidade é system, mundo é user, o próprio é assistant, com rótulo [Nome]',()=>{const mem=require('./memoria-personagem'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-papel-'));mem.ativar(d);try{assert(mem.semear('joao').semeado,'semente de identidade');mem.registrarTurno('joao','mundo','Vi a maré subir junto do cais.',1);mem.registrarTurno('joao','joao','Consertei a rede perto do cais de madeira.',1);const h=mem.historico('joao');assert.equal(h.length,3);assert.equal(h[0].role,'system');assert(!h[0].content.startsWith('['),'identidade não recebe rótulo de conversa');assert(h[0].content.includes('João'));assert.equal(h[1].role,'user');assert(h[1].content.startsWith('[Mundo] '),'entrada do mundo é user com rótulo');assert.equal(h[2].role,'assistant');assert(h[2].content.startsWith('[João] '),'o próprio texto é assistant');assert(!JSON.stringify(h).includes('Rafael')&&!JSON.stringify(h).includes('cortrajetor'));assert.equal(mem.historico('joao',2).length,2,'limite do histórico respeitado')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M1: memória isolada — a experiência de João não existe na da Maria nem na do Ícaro',()=>{const mem=require('./memoria-personagem'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-iso-'));mem.ativar(d);try{assert.notEqual(mem.dirDe('joao'),mem.dirDe('maria'),'diretórios distintos');for(const id of ['joao','maria','icaro'])mem.semear(id);mem.registrarTurno('joao','mundo','MARCO-EXCLUSIVO-DO-JOAO: a rede rasgou no cais.',2);mem.registrarTurno('joao','joao','Consertei a rede rasgada no cais de madeira.',2);const dj=JSON.stringify(mem.historico('joao',50));assert(dj.includes('MARCO-EXCLUSIVO-DO-JOAO'),'João tem a própria experiência');for(const outro of ['maria','icaro']){const dump=JSON.stringify(mem.historico(outro,50));assert(!dump.includes('MARCO-EXCLUSIVO-DO-JOAO'),outro+' não vê a experiência de João');assert(!dump.includes('Consertei a rede'),outro+' não vê a ação de João');assert(!fs.readFileSync(path.join(mem.dirDe(outro),'chat.jsonl'),'utf8').includes('MARCO-EXCLUSIVO-DO-JOAO'),outro+': arquivo próprio não contém nada de João')}assert(!JSON.stringify(mem.entradasDiario('maria',10)).includes('Consertei a rede'),'diário da Maria também isolado')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M1: restart — reabrir relê do disco e a experiência continua lá',()=>{const mem=require('./memoria-personagem'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-restart-'));mem.ativar(d);try{mem.semear('maria');mem.registrarTurno('maria','mundo','Amarrei um nó no portão da fazenda.',3);mem.registrarTurno('maria','maria','Amarrei o nó e conferi o portão da fazenda.',3);const antes=mem.historico('maria',50);const inst1=mem.instanciar('maria');const inst2=mem.reabrir('maria');assert.notStrictEqual(inst1,inst2,'instância nova = processo novo');assert.deepStrictEqual(mem.historico('maria',50),antes,'histórico relido do disco, idêntico');assert.equal(inst2.chat.contar(),inst1.chat.contar());assert(Array.isArray(inst2.tracos.carregar().crencas),'subsistema de traços relido do diretório próprio');assert.equal(fs.readFileSync(path.join(mem.dirDe('maria'),'chat.jsonl'),'utf8').split('\n').filter(l=>l.trim()).length,3,'a fonte no disco é o chat.jsonl')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M1: a experiência reaparece no contexto do próprio personagem e nunca no alheio',async()=>{const mem=require('./memoria-personagem'),ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-ctx-'));mem.ativar(d);try{const e=ec.preparar(novo());e.seres.icaro.local='acampamento';e.seres.maria.local='acampamento';e.seres.joao.local='casa_joao';e.seres.lara.local='fogueira';const dec=async(c,a,ser)=>({acao:ser.id==='icaro'&&a.some(x=>x.id==='conviver')?'conviver':ser.id==='maria'&&a.some(x=>x.id==='falar')?'falar':a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'vive este ciclo',origem:'stub'});await rodada(e,{decisor:dec});const ctxI=mem.contexto('icaro'),ctxM=mem.contexto('maria'),ctxJ=mem.contexto('joao');assert(ctxI.historico.some(m=>m.role==='assistant'&&m.content==='[Ícaro] Conversei com Maria em acampamento.'),'a experiência própria está no contexto do próprio');assert(ctxM.historico.some(m=>m.role==='user'&&m.content==='[Ícaro] Conversou comigo em acampamento.'),'o presente recebe o que o outro viveu');assert(!JSON.stringify(ctxJ.historico).includes('Conversou comigo'),'João não recebe conversa alheia');assert(!JSON.stringify(ctxJ.historico).includes('Conversei com Maria'),'nem a conversa dos outros');assert(ctxI.trajetoriaRecente.length>0,'trajetória recente vem do diário');assert(ctxI.trajetoriaRecente.every(x=>x.tipo==='experiencia'&&x.resposta_icaro.length>=15));assert(ctxI.trajetoriaRecente.some(x=>x.resposta_icaro==='Conversei com Maria em acampamento.'),'a própria experiência reaparece na trajetória');assert(!JSON.stringify(ctxJ.trajetoriaRecente).includes('Conversei com Maria'),'trajetória também isolada')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M1: compactação sem perda — arquiva tudo, preserva âncoras e mantém subsistemas byte-idênticos',()=>{const mem=require('./memoria-personagem'),ec=require('./ecossistema'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-compact-'));mem.ativar(d);try{ec.preparar(novo());const inst=mem.instanciar('joao');for(let i=0;i<40;i++){const ruido=i>=10&&i<30&&i%2===0;inst.chat.appendTurno(i%2?'mundo':'joao',ruido?'ok':'SUBSTANCIAL-'+i+': o que aconteceu neste ciclo do mundo.',mem.quandoDoCiclo(i))}const antes=inst.chat.carregarTodos();assert(antes.length>25,'gatilho do compactador (25 turnos)');const r=mem.compactarSePrecisar('joao');assert.equal(r.compactado,true,'compactou acima do limiar: '+JSON.stringify(r));const depois=inst.chat.carregarTodos();assert(depois.length<antes.length,'trim removeu só ruído do meio');assert(depois[0].id===antes[0].id&&depois[0].quem==='system','âncora da identidade preservada');assert(depois.some(t=>t.texto&&t.texto.includes('SUBSTANCIAL-11')),'experiência substantiva do meio preservada');assert(!depois.some(t=>t.texto==='ok'),'ruído do meio saiu do chat');assert(depois.some(t=>t.tipo==='marcador_compactacao'),'marcador de compactação registrado');const arq=path.join(mem.dirDe('joao'),'chat-arquivado.jsonl'),linhas=fs.readFileSync(arq,'utf8').split('\n').filter(l=>l.trim()).map(l=>JSON.parse(l));assert(linhas.length>=antes.length,'TUDO foi arquivado, nada apagado ('+linhas.length+'/'+antes.length+')');for(const m of mem.MODULOS){const a=fs.readFileSync(path.join(mem.FONTE,m));const b=fs.readFileSync(path.join(mem.dirDe('joao'),m));assert(a.equals(b),m+' byte-idêntico à fonte')}assert(Array.isArray(inst.tracos.carregar().crencas)&&Array.isArray(inst.v2.carregar().fatos),'subsistemas seguem legíveis no diretório próprio')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M1: checkpoint de identidade próprio antes da décima entrada — o texto do ICAROOVO nunca aparece',()=>{const mem=require('./memoria-personagem'),CKPT=require('./cerebro-icaro/checkpoint-identidade'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m1-ckpt-'));mem.ativar(d);try{mem.semear('maria');for(let i=1;i<=9;i++)mem.registrarTurno('maria','mundo','Entrada do mundo número '+i+' no ciclo '+i+'.',i);let turnos=mem.instanciar('maria').chat.carregarTodos();assert.equal(turnos.filter(t=>t.quem==='system').length,1,'nenhum checkpoint antes da décima');mem.registrarTurno('maria','mundo','Entrada do mundo número 10 no ciclo 10.',10);turnos=mem.instanciar('maria').chat.carregarTodos();const sist=turnos.filter(t=>t.quem==='system');assert.equal(sist.length,2,'checkpoint injetado antes da décima entrada');assert.equal(sist[1].texto,mem.textoIdentidade('maria'),'o texto é a identidade da Maria');assert(CKPT.deveInjetarCheckpoint(10,10)===true&&CKPT.deveInjetarCheckpoint(9,10)===false,'mecanismo real do ICAROOVO (a cada 10)');assert(turnos[turnos.length-1].texto.includes('número 10'),'a décima entrada vem depois do checkpoint');assert(!/Rafael|cortrajetor|trajectoria corticalis/.test(JSON.stringify(turnos)),'a identidade é nossa, nunca a do Ícaro')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M2: o contexto da decisão seguinte entrega a experiência vivida do próprio personagem',async()=>{const mem=require('./memoria-personagem'),ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{montarContexto}=require('./cerebro-personagem'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m2-ctx-'));mem.ativar(d);try{const e=ec.preparar(novo());e.seres.icaro.local='acampamento';e.seres.maria.local='acampamento';e.seres.joao.local='casa_joao';const dec=async(c,a,ser)=>({acao:ser.id==='icaro'&&a.some(x=>x.id==='conviver')?'conviver':a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'vive este ciclo',origem:'stub'});await rodada(e,{decisor:dec});const ctx=montarContexto(e,e.seres.icaro,[]);assert(ctx.memoriaVivida&&Array.isArray(ctx.memoriaVivida.historico),'memória vivida entregue ao contexto');assert(ctx.memoriaVivida.historico.some(m=>m.role==='assistant'&&m.content.includes('Conversei com Maria')),'o que ele viveu chega à decisão seguinte (princípio do M1/M2)');assert(ctx.memoriaVivida.historico[0].role==='system'&&ctx.memoriaVivida.historico[0].content.includes('Ícaro'),'identidade no próprio histórico');assert(ctx.memoriaVivida.trajetoriaRecente.length>0&&ctx.memoriaVivida.trajetoriaRecente.every(r=>r.tipo==='experiencia'&&r.resposta_icaro.length>=15),'trajetória recente no contexto');assert(!/Rafael|cortrajetor|trajectoria corticalis/.test(JSON.stringify(ctx.memoriaVivida)),'nada do ICAROOVO no contexto')}finally{mem.desligar();fs.rmSync(d,{recursive:true,force:true})}});
await t('M2: memória vivida é do próprio — nunca a alheia — e fica inerte com o adaptador desligado',()=>{const mem=require('./memoria-personagem'),ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m2-iso-'));mem.ativar(d);const e=ec.preparar(novo());try{mem.registrarTurno('joao','mundo','MARCO-M2-EXCLUSIVO-DO-JOAO: vi a canoa passar.',1);mem.registrarTurno('joao','joao','Acompanhei a canoa passar perto do cais de madeira.',1);const ctxJ=montarContexto(e,e.seres.joao,[]),ctxM=montarContexto(e,e.seres.maria,[]),ctxI=montarContexto(e,e.seres.icaro,[]);assert(ctxJ.memoriaVivida&&JSON.stringify(ctxJ.memoriaVivida).includes('MARCO-M2-EXCLUSIVO-DO-JOAO'),'João vê a própria experiência');assert(!JSON.stringify(ctxM.memoriaVivida).includes('MARCO-M2-EXCLUSIVO-DO-JOAO'),'a Maria não vê a experiência do João');assert(!JSON.stringify(ctxI.memoriaVivida).includes('Acompanhei a canoa'),'nem o Ícaro')}finally{mem.desligar()}assert.strictEqual(montarContexto(e,e.seres.joao,[]).memoriaVivida,null,'adaptador desligado: contexto sem memória vivida (inerente)');fs.rmSync(d,{recursive:true,force:true})});
await t('M2: adaptador mapeia a experiência vivida como fatos — nunca ordens — e só com o adaptador ativo',async()=>{const mem=require('./memoria-personagem'),ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),{montarContexto}=require('./cerebro-personagem'),ad=require('./adaptador-cerebro-icaro'),d=fs.mkdtempSync(path.join(os.tmpdir(),'ilha-m2-fato-'));mem.ativar(d);let e;try{e=ec.preparar(novo());e.seres.icaro.local='acampamento';e.seres.maria.local='acampamento';e.seres.joao.local='casa_joao';const dec=async(c,a,ser)=>({acao:ser.id==='icaro'&&a.some(x=>x.id==='conviver')?'conviver':a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:'vive este ciclo',origem:'stub'});await rodada(e,{decisor:dec});const m=ad.mapearContextoParaIcaro(montarContexto(e,e.seres.icaro,[]));assert(m.fatos.some(f=>f.startsWith('Vivi: ')),'experiência vivida vira fato');assert(m.fatos.every(f=>typeof f==='string'),'tudo string');assert(!m.fatos.some(f=>/precisa beber|deve fugir|v[áa] para|fa[çc]a a miss[ãa]o|deve ir/i.test(f)),'só fatos, nunca ordens');assert(m.fatos.filter(f=>f.startsWith('Vivi: ')).length<=3,'só as experiências recentes (nunca o diário inteiro)')}finally{mem.desligar()}const semVivi=ad.mapearContextoParaIcaro(montarContexto(e,e.seres.icaro,[]));assert(!semVivi.fatos.some(f=>f.startsWith('Vivi: ')),'adaptador desligado: nenhuma experiência vaza para os fatos');fs.rmSync(d,{recursive:true,force:true})});
await t('LARA: irmã do Ícaro — identidade, moradia na casa do acampamento e laço de irmãos entregues ao cérebro',()=>{const ec=require('./ecossistema'),{montarContexto}=require('./cerebro-personagem'),e=ec.preparar(novo());const l=e.seres.lara;assert.equal(l.nome,'Lara');assert.equal(l.status,'vivo');assert.equal(l.casa,'casa_icaro','mora na casa do irmão, junto ao acampamento');assert(l.personalidade.length>=4&&l.personalidade.includes('independente'),'traços próprios');assert.equal(l.historia.residencia,'casa_icaro');assert(/irmã do Ícaro/.test(l.cortex.biografia.passado),'passado declara a irmã');assert(l.cortex.biografia.conhecimentos.some(c=>c.includes('Ícaro é meu irmão')),'sabe que é irmã dele');assert.equal(l.cortex.idade,28);const ctx=montarContexto(e,l,[]);assert.equal(ctx.cortex.identidade.nome,'Lara');assert(ctx.historicoRelacoes.icaro&&/irmã/.test(ctx.historicoRelacoes.icaro.texto),'relação de irmãos no contexto');assert(e.relacoes.lara.icaro>0&&e.relacoes.icaro.lara>0,'irmãos se conhecem nos dois lados');validar(e)});
await t('CASAL: João e Maria moram na mesma casa; cada um tem a moradia no próprio diário de bordo, uma vez só',()=>{const ec=require('./ecossistema'),e=ec.preparar(novo());assert.equal(e.seres.joao.casa,'casa_joao');assert.equal(e.seres.maria.casa,'casa_joao','o casal divide a casa perto do bosque');assert.equal(e.seres.icaro.casa,'casa_icaro');assert.equal(e.seres.lara.casa,'casa_icaro','Lara mora na casa do irmão, com o Ícaro');const moradia=id=>e.seres[id].cortex.diario.filter(d=>d.ciclo===0&&d.acao==='moradia');for(const id of ['joao','maria','icaro','lara']){const m=moradia(id);assert.equal(m.length,1,id+': moradia escrita uma única vez');assert.equal(m[0].consequencia,null,'é fato de vida, não consequência calculada');assert.equal(typeof m[0].motivo,'string')}assert(moradia('joao')[0].motivo.includes('Maria'),'o João escreve que mora com a Maria');assert(moradia('maria')[0].motivo.includes('João'),'a Maria escreve que mora com o João');assert(/irmã/.test(moradia('icaro')[0].motivo),'o Ícaro escreve que mora com a irmã');assert(/irmão/.test(moradia('lara')[0].motivo),'a Lara escreve que mora com o irmão');ec.preparar(e);assert.equal(moradia('joao').length,1,'preparar de novo não duplica a entrada');assert.equal(e.seres.joao.cortex.diario.filter(d=>d.ciclo===0).length,1,'só existe a moradia no ciclo 0')});
await t('CASAL: moradia do casal normaliza a casa antiga e nunca sobrescreve uma moradia escolhida depois',()=>{const ec=require('./ecossistema'),e=ec.preparar(novo());assert.equal(e.seres.maria.casa,'casa_joao');e.seres.maria.casa='casa_maria';ec.preparar(e);assert.equal(e.seres.maria.casa,'casa_joao','o padrão antigo vira a casa do casal');e.seres.maria.casa='casa_icaro';ec.preparar(e);assert.equal(e.seres.maria.casa,'casa_icaro','escolha posterior é do personagem: respeitada')});
await t('VIDA DIÁRIA: banho existe só onde há água e limpa; arrumar casa existe só na própria moradia e alivia',()=>{const e=novo(),s=e.seres.joao;s.local='acampamento';assert(!acoes(e,s).some(a=>a.id==='banho'),'longe da água não dá para banhar');assert(!acoes(e,s).some(a=>a.id==='arrumar_casa'),'fora da própria moradia não há o que arrumar');s.local='rio';assert(acoes(e,s).some(a=>a.id==='banho'),'no rio dá para banhar');assert(!acoes(e,s).some(a=>a.id==='arrumar_casa'),'na água não se arruma casa');s.local='casa_maria';assert(!acoes(e,s).some(a=>a.id==='arrumar_casa'),'casa dos outros não é a dele');s.local=s.casa='casa_joao';s.necessidades.frustracao=60;assert(acoes(e,s).some(a=>a.id==='arrumar_casa'),'na própria casa dá para arrumar');s.local='rio';s.necessidades.higiene=10;executar(e,s,'banho');assert(s.necessidades.higiene>=65,'banho limpa de verdade');s.local=s.casa='casa_joao';const f=s.necessidades.frustracao;executar(e,s,'arrumar_casa');assert(s.necessidades.frustracao<f-3&&s.necessidades.satisfacao>50,'arrumar casa alivia e dá satisfação')});
await t('VIDA DIÁRIA: o ciclo pode escolher banho e arrumar casa — atividade atual e diário de bordo registram o vivido',async()=>{const ec=require('./ecossistema'),{rodada}=require('./rodada-autonoma'),e=ec.preparar(novo());e.seres.icaro.local='rio';e.seres.icaro.necessidades.higiene=5;e.seres.joao.local='casa_joao';e.seres.joao.necessidades.frustracao=70;const dec=async(c,a,ser)=>({acao:ser.id==='icaro'&&a.some(x=>x.id==='banho')?'banho':ser.id==='joao'&&a.some(x=>x.id==='arrumar_casa')?'arrumar_casa':a.some(x=>x.id==='observar')?'observar':a[0].id,motivo:ser.id==='icaro'?'estou sujo do rio para casa':ser.id==='joao'?'a casa merece uma arrumada':'observa o ciclo',origem:'stub'});await rodada(e,{decisor:dec});const ic=e.seres.icaro,jo=e.seres.joao;assert.equal(ic.acao,'banho','atividade atual exposta ao observador');assert.equal(ic.motivo,'estou sujo do rio para casa');assert(ic.necessidades.higiene>50,'o banho aconteceu mesmo');assert(ic.cortex.diario.some(d=>d.acao==='banho'&&d.motivo==='estou sujo do rio para casa'&&d.consequencia&&d.consequencia.quantidade===1),'diário do próprio ser registra o banho');assert.equal(jo.acao,'arrumar_casa');assert(jo.necessidades.frustracao<70,'arrumar aliviou');assert(jo.cortex.diario.some(d=>d.acao==='arrumar_casa'),'diário do próprio ser registra a arrumação');assert(!ic.cortex.diario.some(d=>d.acao==='arrumar_casa'),'a arrumação do João não vaza no diário do Ícaro');assert(e.historico.decisoes.some(d=>d.serId==='icaro'&&d.acao==='banho'&&d.motivo==='estou sujo do rio para casa'),'linha do tempo registra a decisão');assert(typeof e.seres.maria.acao==='string'&&typeof e.seres.lara.acao==='string','todos expõem a atividade corrente para o visualizador')});
console.log('RESULTADO '+total+' testes OK');
})().catch(e=>{console.error(e);process.exitCode=1});
